export const RF_MODELS=['uma-mean-power-fixed-heights-v1','uma-element-fixed-heights-v2','uma-uniform-panel-fixed-heights-v3','uma-source-cells-fixed-heights-v4','uma-source-patterns-fixed-heights-v5','uma-los-receiver-fixed-heights-v6'];
export const RF_REASONS={supported:'Supported model result','model-domain':'Outside the model distance or frequency domain','near-field':'Inside the antenna far-field boundary','below-output':'Complete-cell power is below the model output range','cell-incomplete':'Another assigned port blocks the complete cell','not-assigned':'Not assigned in this frozen run','polarization-null':'Ideal reference polarization null (zero collected power)'};
const finite=(n,low,high,label)=>{if(!Number.isFinite(n)||n<low||n>high)throw Error(`Invalid frozen ${label}.`);return n;};

export function summarizeReview(result,threshold,margin=null){
 finite(threshold,-300,90,'review threshold');if(margin!==null&&(!Number.isFinite(margin)||margin<0||margin>30))throw Error('Enter an assumed sensitivity half-width from 0 to 30 dB, or leave it blank.');
 const summary={total:result.rows.length,supported:0,unavailable:0,aboveMean:0,belowMean:0,aboveRange:0,belowRange:0,crossesThreshold:0,paired:0,unpaired:0,currentOnly:0,referenceOnly:0,neither:0,minPowerDbm:null,maxPowerDbm:null,minDeltaDb:null,maxDeltaDb:null,reasons:{},referenceReasons:{},sensitivity:margin===null?null:{kind:'bounded-study-assumption',halfWidthDb:margin,deltaHalfWidthDb:2*margin,calibrated:false}};
 for(const row of result.rows){if(row.reference?.rxDbm===null)summary.referenceReasons[row.reference.status]=(summary.referenceReasons[row.reference.status]||0)+1;const a=row.current;if(a.rxDbm!==null){summary.supported++;summary.minPowerDbm=Math.min(summary.minPowerDbm??Infinity,a.rxDbm);summary.maxPowerDbm=Math.max(summary.maxPowerDbm??-Infinity,a.rxDbm);if(a.rxDbm>=threshold)summary.aboveMean++;else summary.belowMean++;if(margin!==null){if(a.rxDbm-margin>=threshold)summary.aboveRange++;else if(a.rxDbm+margin<threshold)summary.belowRange++;else summary.crossesThreshold++;}}else{summary.unavailable++;summary.reasons[a.status]=(summary.reasons[a.status]||0)+1;}if(row.deltaDb!==null){summary.paired++;summary.minDeltaDb=Math.min(summary.minDeltaDb??Infinity,row.deltaDb);summary.maxDeltaDb=Math.max(summary.maxDeltaDb??-Infinity,row.deltaDb);}else if(row.reference){summary.unpaired++;if(a.rxDbm!==null)summary.currentOnly++;else if(row.reference.rxDbm!==null)summary.referenceOnly++;else summary.neither++;}}
 return summary;
}
